def summarize(rows):
    """
    Summarize revenue by region.

    Args:
        rows: A list of dicts, each with keys 'region' and 'revenue'.
              Revenue can be numeric or a string representation of a number.

    Returns:
        A dict mapping region -> total revenue as float.
        Rows with missing or unparseable revenue are ignored.
    """
    result = {}

    for row in rows:
        # Check if row has required keys
        if 'region' not in row or 'revenue' not in row:
            continue

        region = row['region']
        revenue = row['revenue']

        # Try to parse revenue as a number
        try:
            if isinstance(revenue, (int, float)):
                revenue_value = float(revenue)
            elif isinstance(revenue, str):
                revenue_value = float(revenue.strip())
            else:
                continue
        except (ValueError, TypeError):
            # Skip rows with unparseable revenue
            continue

        # Accumulate revenue by region
        if region not in result:
            result[region] = 0.0
        result[region] += revenue_value

    return result

